L('html-text-basics',
  'Text Tags - मजकुराची ओळख', 'Text Tags - शीर्षक, परिच्छेद आणि मजकूर',
  'h1-h6, p, br, hr, pre, blockquote, q, abbr, cite, dfn, address, time, data.',
  [
   S('1. शीर्षक - h1 ते h6',
     'मजकूर व्यवस्थित मांडण्यासाठी सर्वात महत्त्वाचे नियंत्रण म्हणजे शीर्षक. HTML मध्ये सहा पातळ्यांची शीर्षके आहेत: <h1>, <h2>, <h3>, <h4>, <h5>, <h6>.\n\n<h1> सर्वात मोठं आणि सर्वात महत्त्वाचं. पेजवर सहसा एकच <h1> वापरतात — ते पेजचं मुख्य नाव. <h2> उपविभाग, <h3> त्याच्यातला उपविभाग — असे क्रमाने.\n\nशीर्षकांचा क्रम कधीही मोडू नका. h1 नंतर थेट h4 — रचना गोंधळते आणि search engines वाचताना क्रमाचा अर्थ लावतात.\n\nशीर्षकाला सर्वस्वी मोठे अक्षर करण्यासाठी वापरू नका; तर व्यवस्थित क्रम द्यायला वापरा. आकार नंतर CSS ठरवेल.\n\nशीर्षक हा पेजचा नकाशा असतो. वाचक आणि machine दोघांनाही त्याचा क्रम सांगतो.',
     '<h1>मुख्य शीर्षक</h1>\n<h2>पहिला विभाग</h2>\n<h3>उपविभाग</h3>\n<h4>छोटा उपविभाग</h4>\n<h5>अजून छोटा</h5>\n<h6>सर्वात लहान</h6>'),
   S('2. परिच्छेद - p, br, hr',
     'सर्वात सामान्य मजकूर block म्हणजे <p> — paragraph. प्रत्येक <p> स्वतःच्या block मध्ये, बहुतेकदा वर-खाली थोडी जागा घेऊन दिसतो.\n\nHTML मध्ये enter दाबणे (नवीन ओळ) फारसा अर्थ देत नाही. एकाहून अधिक जागा एक ठिकाणी मोजल्या जातात. त्यामुळे नवीन ओळ आणायची असेल तर <br> वापरतात.\n\n<br> म्हणजे break — एक void element. कविता, पत्ते, नोंदींच्या ओळीत तो उपयुक्त. परंतु मोठा मजकूर वेगळे करण्यासाठी नव्हे — ते <p> चं काम.\n\n<hr> म्हणजे horizontal rule — एक आडवी रेषा. विषय बदलला, भाग संपला हे दाखवण्यासाठी. <hr> देखील void element.\n\nओळी, रेषा यांचा सजावटीतला उपयोग नंतर CSS करेल; इथे ते रचनेचे घटक आहेत.',
     '<p>मराठी शिकूया. हा एक साधा परिच्छेद आहे.</p>\n<p>दुसरा परिच्छेद — नवीन विषय.</p>\nकवितेची ओळ १<br>\nकवितेची ओळ २<br>\nकवितेची ओळ ३\n<hr>\n<p>नवीन भागाची सुरुवात.</p>'),
   S('3. pre आणि समान वापर',
     'कधीकधी आपल्याला मजकूर नेमका तसाचच दाखवायचा असतो — जागा, ओळी, इंडेंटेशन सगळं. त्यासाठी <pre> आहे.\n\n<pre> मध्ये ब्राउझर रिकाम्या जागा आणि ओळींचा आदर करतो. कोड स्निपेट, ASCII कला, आकडेवारीची सारणी — हे <pre> चे क्षेत्र.\n\n<pre> मध्ये लिहिलेला मजकूर संगणक आधी नमूद केलेल्या फॉन्टने दाखवतो. त्यामुळे सारणी वाचण्यास सोपी जाते.\n\n<blockquote> मोठा उद्धरण (quotation) दाखवतो — दुसऱ्याच्या शब्दांचा मोठा भाग. ब्राउझर त्याला थोडं आतलं ठेवतो.\n\n<q> लहान उद्धरण दाखवतो — मजकुरातच. जरा तपशीलाकडे: blockquote आणि q चा वापर original मजकूर दाखवताना traction देतो.',
     '<pre>\n  रोहिणी       प्रभात\n  ही सातत्याने राहते\n    दररोज लिहिते\n</pre>\n<blockquote>\n  मराठी भाषा ही आपली मातृभाषा आहे.\n</blockquote>\n<p>ती म्हणाली: <q>उद्या सकाळी ये</q>.</p>'),
   S('4. abbr, cite, dfn',
     'संक्षेपांना योग्य अर्थ देण्यासाठी <abbr> वापरतात. title attribute मध्ये पूर्ण रूप लिहितात. उदा. <abbr title="हिंदुस्तानी भाषा">HTML</abbr> — ब्राउझर हळूवार नाव दाखवतो.\n\n<cite> कामाच्या शीर्षकासाठी — पुस्तकाचं नाव, चित्रपटाचं नाव. हे display मध्ये इटालिक दिसते. उदा. <cite>श्यामची आई</cite>.\n\n<dfn> व्याख्या देताना वापरतात — तुम्ही पहिल्यांदा एक term समजावत आहात हे सूचित करतो. प्रथम उपयोगावर तो ठळक दिसतो.\n\nही तिन्ही tags आर्थिक नसून अर्थपूर्ण आहेत. ती search engines आणि सहाय्यक साधनांना मौल्यवान माहिती देतात.\n\nयोग्य tags वापरल्याने मजकूर वाचकाला आणि machine दोघांनाही चांगला समजतो.',
     '<p><abbr title="HyperText Markup Language">HTML</abbr> शिकत आहोत.</p>\n<p><cite>श्यामची आई</cite> हे पुस्तक प्रसिद्ध आहे.</p>\n<p><dfn>Markup</dfn> म्हणजे मजकुराला रचना देणारी भाषा.</p>'),
   S('5. address, time, data',
     'संपर्क माहिती दाखवण्यासाठी <address> वापरतात — पत्ता, email, फोन. हे body च्या मजकुरात अधिकार देते.\n\n<time> वेळ आणि तारीख दाखवण्यासाठी. datetime attribute मध्ये मशीन वाचण्यासारखा format: <time datetime="2026-09-09">सप्टेंबर २०२६</time>.\n\n<data> सामान्य डेटा-मूल्य साठवण्यासाठी. value attribute मध्ये किमती संग्रहित होतात, पण पेजवर वेगळा मजकूर दिसतो.\n\nहे तिन्ही tags मजकुरातच राहतात, त्यांचा अर्थ बदलत नाही. तरीही ते machine ला सविस्तर माहिती देतात — जसं calendar एकत्रीकरण किंवा संपर्क निर्यात.\n\nआधुनिक वेबमध्ये ही छोटी "सिमेंटिक" मदत मोलाची ठरते.',
     '<address>\n  महाराष्ट्र मंडळ,\n  पुणे ४१०<br>\n  संपर्क: samp@example.com\n</address>\n<p>मीटिंग <time datetime="2026-09-10">१० सप्टेंबर</time> ला आहे.</p>\n<p>उत्पादन क्रमांक <data value="0187">मराठी-ए-१८७</data>.</p>'),
   S('6. भावना आणि योग्य निवड',
     'मजकूर tags कधी वापरायचे हेही जाणून घेऊया. फक्त मोठे अक्षर किंवा ठळक दिसण्यासाठी नाही; तर अर्थ देण्यासाठी.\n\nशीर्षकासाठी h1-h6, परिच्छेदासाठी p, संक्षेपासाठी abbr, उद्धरणासाठी blockquote किंवा q — प्रत्येकाचा स्वतःचा अर्थ.\n\nसजावटीसाठी tags निवडू नका. <b> मुळे धाडस ठळक होतं, परंतु <strong> मुळे महत्त्व सांगतो. तो फरक पुढच्या धड्यात कळेल.\n\nहे सर्व नियोजन मजकुराची रचना स्वच्छ करतं. वाचक पटकन स्कॅन करतो; machine पटकन समजतं.\n\nप्रत्येक tag ला योग्य ठिकाणी वापरा — हेच या धड्याचं ध्येय.',
     '<h2>भाषा अभिमान</h2>\n<p>मराठी ही समृद्ध भाषा आहे, असे <strong>विद्वान</strong> मानतात.</p>\n<p>दैनंदिन वापरात ती वाढते आणि टिकते.</p>'),
   S('Mini Project',
     'आता एकच उदाहरणात सर्व थांबवूया: "माझा आवडता लेखक" असं पेज बनवा.\n\nh1 मध्ये लेखकाचं नाव. h2 मध्ये दोन विभाग — परिचय आणि पुस्तकं.\n\nपरिचय दोन p मध्ये. पुस्तकं एका blockquote मध्ये ओळ करा.\n\nपत्ता address मध्ये, एक time आणि एक data टाका.\n\nअशी रचना केल्यावर वेबपेज साकारतो आणि पुढील धडा सोपा होतो.',
     '<!DOCTYPE html>\n<html lang="mr">\n  <head>\n    <meta charset="utf-8">\n    <title>माझा आवडता लेखक</title>\n  </head>\n  <body>\n    <h1>श्री. लेखक</h1>\n    <p>ते प्रसिद्ध मराठी लेखक आहेत.</p>\n    <h2>पुस्तकं</h2>\n    <blockquote>"मराठी वाङ्मय" हे पुस्तक प्रसिद्ध.</blockquote>\n    <address>पुणे, महाराष्ट्र</address>\n  </body>\n</html>'),
  ],
  ['h1 ते h6 मध्ये क्रम कसा ठेवायचा?', 'pre आणि p मध्ये फरक?', 'abbr मध्ये काय लिहितात?', 'address केव्हा वापरतात?'],
  [{'q':'सर्वात मोठं शीर्षक?','o':['h1','h6','p','div'],'c':0},
   {'q':'कोणता void element नाही?','o':['h1','br','hr','img'],'c':0},
   {'q':'मोठा उद्धरण कोणता?','o':['blockquote','q','p','cite'],'c':0},
   {'q':'वेळ दाखवण्यासाठी?','o':['time','date','p','hr'],'c':0}],
  {'prompt':'h2 आणि p च्या दोन उपविभागांचं पेज बनवा','starterCode':'<h1>वेब शिकून</h1>\n<h2>मराठीतून</h2>\n<p>सोपं आणि स्पष्ट.</p>','expectedOutput':'Renders शीर्षके आणि परिच्छेद'},
  ['शीर्षकांचा क्रम महत्त्वाचा का?', 'pre कशासाठी उपयुक्त?'],
  ['html-structure', 'html-text-formatting'],
  'html-structure', 'html-text-formatting')

