# 3. TEXT FORMATTING  (Master 3)
# =====================================================================
L('html-text-formatting',
  'Text Formatting - मजकूर सजावट', 'Text Formatting - ठळक, तिरपे आणि अर्थपूर्ण वापर',
  'strong, b, em, i, mark, small, del, ins, s, u, sub, sup, kbd, code, samp, var.',
  [
   S('1. ठळक मजकूर - strong आणि b',
     'मजकूर ठळक करण्याचे दोन मार्ग आहेत: <strong> आणि <b>. दिसण्यात दोघेही जवळपास सारखे, पण अर्थ वेगळा.\n\n<strong> महत्त्व देतो — वाचकाला विशेष लक्ष द्यायला सांगतो. स्क्रीन रीडर ते जोराने वाचतो. उदा. <strong>चेतावणी</strong>.\n\n<b> फक्त दृश्य ठळक — जुन्या काळी "bold" साठी. त्याला अर्थिक महत्त्व नाही. कीवर्ड्स सजवताना वापरतात.\n\nनियम: महत्त्व व्यक्त करण्यासाठी strong, दृश्य थाळ्यासाठी b. काही मजकूर empty नाही.\n\nजेव्हा दोघांचा उपयोग शक्य, तेव्हा अर्थ देणारा strong निवडा — तोच आधुनिक दृष्टीकोन.',
     '<p><strong>लक्ष द्या:</strong> ही चेतावणी महत्त्वाची आहे.</p>\n<p>पुस्तकात <b>टर्म</b> अशा ठळक अक्षरांत देतात.</p>'),
   S('2. तिरपा मजकूर - em आणि i',
     'तिरपा मजकूर दोन प्रकारे: <em> आणि <i>. पुन्हा वेग अर्थातच अर्थ.\n\n<em> भावनिक भर देण्यासाठी — "हेच मला हवं". वाचकाला स्वर कल्पना येतो. Screen reader ते ठळकपणे वाचतो.\n\n<i> फक्त दृश्य तिरपे — तांत्रिक नाम, परकीय शब्द, जहाजाची नावं. उदा. एखादी कला कृती किंवा वनस्पतीचं नाव.\n\nफरक उदाहरण: <em>मला आवडतं</em> म्हणजे भर; <i>गुलाब</i> म्हणजे फक्त तिरपी ओळख.\n\nप्रत्येक वेळी अर्थाशी जुळणारा tag घेणं हे सुदृढ वेबचं लक्षण.',
     '<p>मला <em>हेच</em> पुस्तक वाचायचं आहे.</p>\n<p>उद्यानात <i>गुलाब</i> उमलला.</p>'),
   S('3. mark आणि small',
     '<mark> मजकूर ठळकपणे पिवळसर उघडतो — नोंद किंवा शोधनिकाल दाखवण्यासाठी. त्यामुळे वाचकाचं लक्ष सहज उतरतं.\n\nवापर: शोधताना जुळलेला शब्द, पाठ्यपुस्तकातील महत्त्वाचा भाग, सूचनांमधील आधारीत मजकूर.\n\n<small> मजकूर कमी महत्त्वाचा ठरतो — बारीक टिपा, कॉपीराइट, कायदेशीर तारीख. उदा. © 2026 मराठीकोड. सर्व हक्क राखीव.\n\n<small> ने फॉन्ट आकार कमी होतो, पण मुख्य हेतू अर्थ आहे: हा मजकूर गौण.\n\nसजावटीसाठी छोटा मजकूर CSS ने करू; <small> चा वापर अर्थिक असेल तरच.',
     '<p>तुम्ही <mark>मराठी</mark> चा अभ्यास करत आहात.</p>\n<p><small>© 2026 मराठीकोड. सर्व हक्क राखीव.</small></p>'),
   S('4. बदल - del, ins, s, u',
     'मजकुरात बदल दाखवण्यासाठी चार tags: <del>, <ins>, <s>, <u>.\n\n<del> हटवलेला मजकूर — आडवी रेषा (strikethrough). किंमतीत झालेली घट उदा. "\u20b9१०० <del>\u20b9१२०</del>".\n\n<ins> नव्याने जोडलेला — खालची रेषा किंवा ठळक रंग. तारीख आणि बदल नोंदवण्यासाठी <ins> उपयुक्त.\n\n<s> यापुढे असंभाव्य/निरर्थक मजकूर — जुनं उत्पादन, बंद योजना.\n\n<u> अर्थ नसली तरी विशेष; सहसा misspelling दाखवण्यासाठी वापरतात. लिंकसारखा दिसत असल्याने सावध राहा.\n\nप्रत्येक tag आपला बदल सांगतो — दुरुस्त मजकुराची एक सुरळीत नोंद.',
     '<p>किंमत: \u20b9१०० <del>\u20b9१२०</del></p>\n<p>नवीन अपडेट <ins>आज जोडली</ins>.</p>\n<p><s>जुनी योजना बंद</s></p>\n<p>अगदी <u>चुकीचं</u> स्पेलिंग दाखवतो.</p>'),
   S('5. sub आणि sup',
     '<sub> subscript — खालच्या मजकुरात. रासायनिक सूत्रात: H<sub>2</sub>O — पाण्यातील २.\n\n<sup> superscript — वरच्या मजकुरात. गणित आणि टीपांत: 10<sup>3</sup> = १०००.\n\nदोन्ही छोट्या मजकुरात सूचित होतात. शास्त्रीय दस्तऐवज, समीकरण, सूत्र यात उपयोगी.\n\nतर keyboard shortcuts मध्ये सुद्धा sub- sup वापरले जातात.\n\nइथे लक्षात ठेवा: हे सजावट नव्हे, अर्थिक रचना आहे. सूत्राचं रचनात्मक XXI दर्शन.',
     '<p>रासायनिक सूत्र: H<sub>2</sub>O म्हणजे पाणी.</p>\n<p>गणित: 10<sup>3</sup> = 1000.</p>'),
   S('6. code, kbd, samp, var',
     'संगणकीय मजकुरासाठी चार विशेष tags महत्त्वाचे.\n\n<code> कोडची ओळ दाखवतो — मोनोस्पेस फॉन्टमध्ये. उदा. वापर method(): .\n\n<kbd> keyboard की दाखवतो — वापरकर्ता जी की दाबतो. उदा. दाबा <kbd>Ctrl</kbd> + <kbd>P</kbd>.\n\n<samp> program च्या output चा नमुना दाखवतो. संगणक return करतो तो.\n\n<var> व्हेरिएबल दाखवतो — गणितात x, कोडात नाव. उदा. <var>x</var> + <var>y</var> = परिणाम.\n\nचारही भेद स्पष्ट केल्यावर तांत्रिक दस्तऐवज आपोपान स्वच्छ होतो.',
     '<p>चालवा <code>print("नमस्कार")</code>.</p>\n<p>दाबा <kbd>Ctrl</kbd> + <kbd>Enter</kbd>.</p>\n<p>प्रोग्राम म्हणतो: <samp>नमस्कार</samp>.</p>\n<p><var>वय</var> म्हणजे वर्षांची संख्या.</p>'),
   S('Mini Project',
     'आता सर्व formatting एकत्र आणूया: मराठी अभ्यास वेबपेज.\n\nशीर्षक h1 ने. एका p मध्ये strong आणि em. दुसऱ्यात mark आणि sub, sup.\n\nकोड आणि kbd चा एक छोटा भाग आणि एक del-ins उदाहरण ठेवा.\n\nप्रत्येक tag अर्थाशी जुळवा — सजावटीसाठी नाही.\n\nहा धडा संपला की मजकुराची रचना बरोबर मिळते.',
     '<!DOCTYPE html>\n<html lang="mr">\n  <head>\n    <meta charset="utf-8">\n    <title>मजकूर सजावट</title>\n  </head>\n  <body>\n    <h1>मराठीतून वेब</h1>\n    <p><strong>महत्त्वाचे:</strong> दररोज <em>सराव</em> करा.</p>\n    <p>पाणी H<sub>2</sub>O आणि क्षेत्र m<sup>2</sup>.</p>\n    <p>कोड: <code>moksh_role.header()</code></p>\n    <p>दाबा <kbd>Run</kbd>. <s>जुनं बंद</s></p>\n  </body>\n</html>'),
  ],
  ['strong आणि b मध्ये फरक?', 'sub कधी वापरतात?', 'code आणि samp मध्ये काय?', 'del काय दाखवतो?'],
  [{'q':'महत्त्व दाखवण्यासाठी?','o':['strong','b','i','u'],'c':0},
   {'q':'रासायनिक सूत्रात?','o':['sub','sup','kbd','code'],'c':0},
   {'q':'हटवलेला मजकूर?','o':['del','ins','mark','small'],'c':0},
   {'q':'कीबोर्ड की दाखवण्यासाठी?','o':['kbd','samp','var','code'],'c':0}],
  {'prompt':'em + sub + kbd वापरून एकाची रचना बनवा','starterCode':'<p><em>मराठी</em> गोड आहे.</p>','expectedOutput':'Renders तिरपा मराठी शब्द'},
  ['em वि i फरक?', 'mark केव्हा वापरतात?'],
  ['html-text-basics', 'html-lists'],
  'html-text-basics', 'html-lists')

