L('html-lists',
  'Lists - सूची आणि याद्या', 'Lists - मजकूर नियोजनाचा मूलभूत प्रकार',
  'ul, ol, li, dl, dt, dd, nested lists, start, reversed, type, list accessibility.',
  [
   S('1. unordered list - ul, li',
     'मजकुरात याद्या आणखी एक सोपी रचना देते. परिच्छेदाऐवजी — संख्या महत्त्वाची, क्रम नाही, तेव्हा unordered list वापरतात.\n\n<ul> बाहेरचं रचना; आत प्रत्येक ओळ <li> (list item). प्रत्येक <li> वेगळा bullet.\n\nरचना: <ul>\n  <li>एक</li>\n  <li>दोन</li>\n</ul>\n\nBullet गोल किंवा चौकोनी असू शकतो; तो CSS ठरवतो. रचना आधी HTML ची.\n\nसूची म्हणजे फक्त सजावट नव्हे — पदार्थ, चरण, गुणधर्म — यांसारख्या सर्व संग्रहांसाठी सूची वापरा.',
     '<h2>आजचं काम</h2>\n<ul>\n  <li>घर साफ करणे</li>\n  <li>बाजारात जाणे</li>\n  <li>अभ्यास करणे</li>\n</ul>'),
   S('2. ordered list - ol, li',
     'क्रम महत्त्वाचा असतो तेव्हा ordered list वापरतात — <ol> आणि आत <li>.\n\nब्राउझर आपोआप संख्या देते: 1, 2, 3... त्यामुळे तुम्हाला संख्या लिहाव्या लागत नाहीत.\n\nपाककृतीच्या चरणांसाठी, instructions साठी, रँकिंगसाठी <ol> योग्य.\n\n<li> मध्ये कोणताही element असू शकतो — paragraph, चित्र, दुवा, अगदी आणखी सूची.\n\nसंख्या ब्राउझर ठरवतो — म्हणून मजकूर अदलाबदल केला तरी संख्या स्वतःक्रम येतो. हे मोठे सौंदर्य.',
     '<h2>चहा बनवण्याचा क्रम</h2>\n<ol>\n  <li>पाणी उकळते</li>\n  <li>चहा पाने घाला</li>\n  <li>दूध आणि साखर घाला</li>\n  <li>गाळून प्या</li>\n</ol>'),
   S('3. Nested lists',
     'याद्यांच्या आत याद्या — nested list — खोल रचना देतं.\n\n<ul> च्या <li> च्या आत दुसरी <ul> किंवा <ol> लिहितात.\n\nउदा. आवडीच्या विषयांच्या आत उपविषय: प्रत्येक <li> ला स्वतःची उपसूची.\n\nब्राउझर खोलीनुसार bullet बदलतो — वर गोल, पुढे चौकोन, नंतर काळा गोल.\n\nNesting प्रत्येक पातळीवर बंद tags सांभाळा — चुकीचं बंद केल्यास रचना गोंधळते.',
     '<ul>\n  <li>फळं\n    <ul>\n      <li>आंबा</li>\n      <li>केळी</li>\n    </ul>\n  </li>\n  <li>भाज्या\n    <ul>\n      <li>पालक</li>\n      <li>मेथी</li>\n    </ul>\n  </li>\n</ul>'),
   S('4. dl, dt, dd',
     'शब्द आणि त्याची व्याख्या सोबत द्यायची असेल — तर description list वापरतात.\n\n<dl> बाहेर; प्रत्येक term <dt> आणि त्याचं वर्णन <dd>.\n\nउदा. <dl>\n  <dt>HTML</dt>\n  <dd>मजकूराची रचना करणारी भाषा.</dd>\n</dl>\n\nएका <dt> नंतर अनेक <dd> शक्य — पदाचा आणि त्याच्या तपशिलांचा संग्रह.\n\nशब्दकोश, मेण्यू ओळख, FAQs — यांसाठी dl उत्तम. तो हाताळणे आणि वाचणे सोपे.',
     '<dl>\n  <dt>मजकूर</dt>\n  <dd>तुम्ही पेजवर वाचता तो शब्द.</dd>\n  <dt>Tag</dt>\n  <dd>रचना देणारं चिन्ह.</dd>\n  <dt>Style</dt>\n  <dd>रूप देणारं नियम.</dd>\n</dl>'),
   S('5. ol चे attributes',
     'ordered list ला अतिरिक्त attributes देतात तेव्हा संख्या नियंत्रण मिळते.\n\nstart — सुरुवात संख्या. <ol start="5"> प्रथम item क्रमांक ५.\n\nreversed — उलट क्रम. <ol reversed> ३, २, १ असे.\n\ntype — चिन्ह निवड. type="A" मोठी A, B, C; type="a" लहान; type="i" रोमन i, ii, iii.\n\nstart आणि type एकत्र थरात क्रम देता येतो: start="3" type="A".\n\nहे attributes अर्थपूर्ण असतात जेव्हा क्रम नेमका महत्त्वाचा असतो.',
     '<ol start="5">\n  <li>पाचवा</li>\n  <li>सहावा</li>\n</ol>\n<ol reversed>\n  <li>तिसरा</li>\n  <li>दुसरा</li>\n  <li>पहिला</li>\n</ol>\n<ol type="A">\n  <li>पहिलं</li>\n  <li>दुसरं</li>\n</ol>'),
   S('6. सूची आणि प्रवेशयोग्यता',
     'सूची केवळ दिसण्यासाठी नव्हे — ती वाचण्यासाठी रचना देतात.\n\nमेनूमध्ये <ul> वापरल्यास screen reader ला मेनूची रचना सांगता येते. नेव्हिगेशनच्या <nav> मध्ये सूची ठेवा.\n\n<li> च्या आत जास्त मजकूर असेल तर तो एका <p> मध्ये घाला — न्याय्य रचना.\n\nसूचीच्या ओळीत दुवे असल्यास ते inline सुद्धा चालतात; पण सूची त्यांना वेगळं ठेवते.\n\nसूची वापरताना ती खरोखरच सूची असावीच — फक्त ठिपके देण्यासाठी तसा उपयोग करू नका.',
     '<nav>\n  <ul>\n    <li><a href="index.html">मुख्य</a></li>\n    <li><a href="about.html">परिचय</a></li>\n    <li><a href="contact.html">संपर्क</a></li>\n  </ul>\n</nav>'),
   S('Mini Project',
     'आता पाककृती पेज बनवूया — निरनिराळ्या सूची एकत्र.\n\nउपकरणं <ul>, क्रम <ol>, आणि टीपा <dl> ने द्या.\n\nएक चरणात nested <ul> चा वापर करा.\n\nशेवटी एक <ol start="1"> ठीक, घटकांचा क्रम स्वच्छ.\n\nअशा रचनेने मजकूर आणि सूचना दोन्ही स्पष्ट साकारतात.',
     '<!DOCTYPE html>\n<html lang="mr">\n  <head>\n    <meta charset="utf-8">\n    <title>प्रोफाइल</title>\n  </head>\n  <body>\n    <h1>मसाला चहा</h1>\n    <h2>उपकरणं</h2>\n    <ul>\n      <li>पातेले</li>\n      <li>चाळणी</li>\n    </ul>\n    <h2>क्रम</h2>\n    <ol>\n      <li>पाणी उकळते</li>\n      <li>चहा पाने घाला</li>\n    </ol>\n    <dl>\n      <dt>टीप</dt>\n      <dd>गॅस कमी करा.</dd>\n    </dl>\n  </body>\n</html>'),
  ],
  ['ul आणि ol मध्ये फरक?', 'nested list कसा बनवतात?', 'dl म्हणजे काय?', 'start attribute काय करतो?'],
  [{'q':'क्रम नसलेली यादी?','o':['ul','ol','dl','tl'],'c':0},
   {'q':'व्याख्या यादी?','o':['dl','ul','ol','bl'],'c':0},
   {'q':'संख्या ३ पासून सुरू करण्यासाठी?','o':['start="3"','begin="3"','first="3"','init="3"'],'c':0},
   {'q':'उलट क्रमासाठी?','o':['reversed','updown','flip','back'],'c':0}],
  {'prompt':'ul आणि ol दोन्ही वापरून पेज बनवा','starterCode':'<h2>सूची</h2>\n<ul>\n  <li>एक</li>\n</ul>','expectedOutput':'Renders याद्या'},
  ['nested list नियम काय?', 'type attribute चे प्रकार?'],
  ['html-images', 'html-tables'],
  'html-images', 'html-tables')

