# 7. TABLES  (Master 7)
# =====================================================================
L('html-tables',
  'Tables - डेटा सारणी', 'Tables - रांगा आणि स्तंभांत माहिती',
  'table, tr, th, td, thead, tbody, tfoot, colspan, rowspan, caption, colgroup.',
  [
   S('1. table, tr, th, td',
     'संख्यात्मक व तुलनात्मक माहिती सारणीत बसते. HTML मध्ये <table> वापरतात.\n\nसारणीत रांगा असतात — त्या <tr> (table row) ने बनतात. प्रत्येक रांगेच्या आत घटक असतात.\n\nघटक दोन प्रकारचे: <th> म्हणजे header (शीर्षक) आणि <td> म्हणजे data (आकडा/मजकूर).\n\n<tr>\n  <th>नाव</th>\n  <td>रमेश</td>\n</tr>\n\nप्रथम रांगेत th दिल्यास ब्राउझर शीर्षक ठळक आणि मध्यवर्ती दाखवतो.\n\nसारणी डेटासाठी; layout साठी नाही — हा सुवर्ण नियम आठवा.',
     '<table>\n  <tr>\n    <th>भाषा</th>\n    <th>वक्ते</th>\n  </tr>\n  <tr>\n    <td>मराठी</td>\n    <td>९५ कोटी</td>\n  </tr>\n  <tr>\n    <td>हिंदी</td>\n    <td>६० कोटी</td>\n  </tr>\n</table>'),
   S('2. thead, tbody, tfoot',
     'मोठ्या सारणीत रचना तीन भाग करू शकतो: thead, tbody, tfoot.\n\n<thead> शीर्षक रांगा. <tbody> मुख्य डेटा. <tfoot> शेवटचा सारांश.\n\nहा विभाग संगणकाला कळतो — printing, scrolling सारख्या वागणुकीला आधार.\n\nthead मध्ये चालतो tr आणि th; tbody मध्ये tr आणि td.\n\ncopy सारणी ही एकाची नेटकी; पण thead-tbody-tfoot दिल्यावर रचना वाचनीय होते.',
     '<table>\n  <thead>\n    <tr><th>महिना</th><th>पाऊस</th></tr>\n  </thead>\n  <tbody>\n    <tr><td>जून</td><td>५० मिमी</td></tr>\n    <tr><td>जुलै</td><td>८० मिमी</td></tr>\n  </tbody>\n  <tfoot>\n    <tr><td>एकूण</td><td>१३० मिमी</td></tr>\n  </tfoot>\n</table>'),
   S('3. caption आणि colgroup',
     'सारणीचं वर्णन caption देते — ते सारणीच्या वर दिसतं.\n\n<caption>एकूण प्रवेश</caption> — सारणीला शीर्षक.\n\n<colgroup> स्तंभांची गटांना माहिती देतो. <col span="2" style="..."> असे दोन स्तंभ एकत्र.\n\ncolgroup चा उपयोग styling सारखे गुण देतानाच नाही; स्तंभ गटबद्ध करतो.\n\ncaption आणि colgroup दोन्ही table च्या सुरुवातीला लिहितात.',
     '<table>\n  <caption>स्पर्धेचे गुण</caption>\n  <colgroup>\n    <col>\n    <col style="background:#f4f4f4">\n  </colgroup>\n  <tr>\n    <th>स्पर्धक</th>\n    <th>गुण</th>\n  </tr>\n  <tr>\n    <td>आर्या</td>\n    <td>९२</td>\n  </tr>\n</table>'),
   S('4. colspan आणि rowspan',
     'सारणीत एक घटक अनेक स्तंभ किंवा रांगा व्यापू शकतो.\n\ncolspan="2" म्हणजे घटक दोन स्तंभांचं क्षेत्र घेतो. उदा. <td colspan="2">.\n\nrowspan="2" म्हणजे घटक दोन रांगांच्या उंचीचा. उत्पादनाचा आराखडा, कॅलेंडर — यांत असा वापर.\n\nसमान रांगेत जेवढा स्तंभ विस्तार, तेवढे घटक कमी लिहितात. मोजणी बरोबर ठेवा.\n\nपटकन चुकायची शक्यता — सारणी काढून मोजून लिहा.',
     '<table>\n  <tr>\n    <th>नाव</th>\n    <th colspan="2">पत्ता</th>\n  </tr>\n  <tr>\n    <td>राम</td>\n    <td>पुणे</td>\n    <td>पिंपरी</td>\n  </tr>\n  <tr>\n    <td rowspan="2">शाळा</td>\n    <td>इयत्ता ७</td>\n    <td>इयत्ता ८</td>\n  </tr>\n</table>'),
   S('5. प्रवेशयोग्य सारणी',
     'सारणी वापरताना screen reader ला रचना कळणं गरजेचं.\n\nthead-th वापरा जेणेकरून header प्रत्येक cell ला जोडला जाईल.\n\nscope attribute: <th scope="col"> किंवा scope="row" — header कोणत्या दिशेला लागू.\n\nसंख्याहीन, कोण्याही अर्थाशिवाय सारणी नको. शीर्षकाने सुबक ठेवा.\n\nही सवय केल्यावर तुमची सारणी scientific way सर्वांना वाचता येते.',
     '<table>\n  <caption>मासिक विक्री</caption>\n  <thead>\n    <tr>\n      <th scope="col">उत्पादन</th>\n      <th scope="col">युनिट</th>\n    </tr>\n  </thead>\n  <tbody>\n    <tr>\n      <th scope="row">पेन</th>\n      <td>१२०</td>\n    </tr>\n    <tr>\n      <th scope="row">वही</th>\n      <td>४५</td>\n    </tr>\n  </tbody>\n</table>'),
   S('6. अर्थ आणि सावधानता',
     'सारणी ही संरचनात्मक साधन नाही — ती डेटा संरचना आहे.\n\nlayout साठी table वापरली असती तर जुन्या जमान्यात; आज CSS layout sांभाळतो.\n\nलहान आकडा, तुलना, किंवा वेळापत्रक — हेच table चे क्षेत्र.\n\nमजकूराबरोबर table मध्ये थोड्याशा आकडे शक्य; पण दिसणे CSS संभाळेल.\n\nHTML मध्ये आकडा मांडा, मग तो कोणत्याही रूपात वाजवता येतो.',
     '<table>\n  <tr>\n    <th>दिवस</th>\n    <th>सकाळ</th>\n    <th>संध्याकाळ</th>\n  </tr>\n  <tr>\n    <td>सोम</td>\n    <td>गणित</td>\n    <td>विज्ञान</td>\n  </tr>\n  <tr>\n    <td>मंगळ</td>\n    <td>मराठी</td>\n    <td>इतिहास</td>\n  </tr>\n</table>'),
   S('Mini Project',
     'आता मासिक आत प्रवेश सारणी बनवूया.\n\nthe-head मध्ये दिवस आणि वेळ. tbody मध्ये दोन-तीन रांगा विषयांच्या.\n\neka घटकाला colspan किंवा rowspan द्या.\n\ncaption आणि scope वापरा. अर्थ असेल तर.\n\nसारणी संपल्यावर डेटा व्यवस्थित, मराठीतून वेब सादर होतो.',
     '<!DOCTYPE html>\n<html lang="mr">\n  <head>\n    <meta charset="utf-8">\n    <title>आठवड्याचे वेळापत्रक</title>\n  </head>\n  <body>\n    <table>\n      <caption>अभ्यास वेळापत्रक</caption>\n      <thead>\n        <tr><th scope="col">दिवस</th><th scope="col">विषय</th></tr>\n      </thead>\n      <tbody>\n        <tr><th scope="row">सोमवार</th><td>मराठी</td></tr>\n        <tr><th scope="row">मंगळवार</th><td>गणित</td></tr>\n      </tbody>\n    </table>\n  </body>\n</html>'),
  ],
  ['th म्हणजे काय?', 'the-एड का वापरतात?', 'colspan काय करतो?', 'caption कुठे लिहितात?'],
  [{'q':'सारणीचा base tag?','o':['table','tbl','grid','list'],'c':0},
   {'q':'शीर्षक cell?','o':['th','td','tr','ta'],'c':0},
   {'q':'दोन स्तंभ विस्तार?','o':['colspan="2"','rowspan="2"','width="2"','span="2"'],'c':0},
   {'q':'सारणीचं शीर्षक?','o':['caption','title','header','note'],'c':0}],
  {'prompt':'the-एड आणि tfoot सह सारणी बनवा','starterCode':'<table>\n  <tr><th>नाव</th></tr>\n  <tr><td>सीता</td></tr>\n</table>','expectedOutput':'Renders सारणी'},
  ['scope काय सांगतो?', 'layout table का नको?'],
  ['html-lists', 'html-forms'],
  'html-lists', 'html-forms')

